<span class="line">    maya_app_dir <span class="token operator">=</span> cmds<span class="token punctuation">.</span>internalVar<span class="token punctuation">(</span>userAppDir<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span></span>
