<span class="line">        self<span class="token punctuation">.</span>tool2_btn<span class="token punctuation">.</span>clicked<span class="token punctuation">.</span>connect<span class="token punctuation">(</span>self<span class="token punctuation">.</span>open_tool2<span class="token punctuation">)</span></span>
